 "content": "from collections import deque


def transform(grid):
    """Count stem-up and stem-down T tetrominoes; encode counts in paired 3x3 panels."""
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = {"up": 0, "down": 0}
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            minr = min(y for y, x in cells)
            maxr = max(y for y, x in cells)
            if len(cells) != 4:
                continue
            top = {x for y, x in cells if y == minr}
            bottom = {x for y, x in cells if y == maxr}
            if len(top) == 1 and len(bottom) == 3:
                counts["up"] += 1
            elif len(top) == 3 and len(bottom) == 1:
                counts["down"] += 1

    out = [[0] * 6 for _ in range(3)]
    slots = ((0, 0), (2, 0), (0, 2), (2, 2))
    for key, color, col_offset in (("up", 3, 0), ("down", 1, 3)):
        for rr, cc in slots[:counts[key]]:
            out[rr][cc + col_offset] = color
    return out
